"""Invoice maths."""


def invoice_total(items, tax):
    """Total for ``items`` (dicts with an ``amount``) including ``tax``."""
    subtotal = sum(item["amount"] for item in items)
    return round(subtotal * (1 + tax), 2)

from .calc import invoice_total


def create_invoice(items, region="US"):
    """Build a simple invoice dict for a region."""
    tax = 0.2 if region == "UK" else 0.0
    return {"items": items, "region": region, "total": invoice_total(items, tax)}

import pytest

from billing import create_invoice, invoice_total

ITEMS = [{"amount": 100.0}]


def test_keyword_only():
    with pytest.raises(TypeError):
        invoice_total(ITEMS, 0.2)


def test_tax_by_keyword():
    assert invoice_total(ITEMS, tax_rate=0.2) == 120.0


def test_discount_before_tax():
    assert invoice_total(ITEMS, tax_rate=0.2, discount_rate=0.1) == 108.0


def test_caller_updated():
    inv = create_invoice(ITEMS, region="UK")
    assert inv["total"] == 120.0

"""Team spend report."""


def summarize(rows):
    """One row per team: ``{"team", "total", "n"}``.

    Sorted by total descending, ties by team name ascending.
    """
    groups = {}
    for row in rows:
        groups.setdefault(row["team"], []).append(row["score"])

    out = [{"team": team, "total": round(sum(scores), 2), "n": len(scores)}
           for team, scores in groups.items()]
    out.sort(key=lambda r: str(r["total"]), reverse=True)
    return out

